#pragma once

#include <stdint.h>
#include "stream_data.h"

// One cluster owns every Clusters-th group of tpb elements. The operation is
// the same independent FP32 case generated by kernels/stream/run.py.
template <uint32_t Clusters>
static inline void stream_apply(uint32_t tid, uint32_t tpb, uint32_t cluster) {
  const float *a = (const float *)STREAM_A_ADDR;
  const float *b = (const float *)STREAM_B_ADDR;
  const float *c = (const float *)STREAM_C_ADDR;
  float *out = (float *)STREAM_OUT_ADDR;
  const uint32_t step = tpb * Clusters;
  for (uint32_t i = cluster * tpb + tid; i < STREAM_N; i += step) {
#if STREAM_KIND == 0
    out[i] = a[i];
#elif STREAM_KIND == 1
    out[i] = 2.0f * c[i];
#elif STREAM_KIND == 2
    out[i] = a[i] + b[i];
#elif STREAM_KIND == 3
    out[i] = b[i] + 2.0f * c[i];
#else
#error Unknown STREAM operation
#endif
  }
}
